// ── LRU Cache: O(1) get and put ────────────────────────────────
class LRUCache {
  #cap;
  #map;   // key -> DLL node
  #head;  // dummy MRU sentinel
  #tail;  // dummy LRU sentinel

  constructor(capacity) {
    this.#cap  = capacity;
    this.#map  = new Map();
    // Sentinel nodes — never hold real data
    this.#head = { key: null, val: null, prev: null, next: null };
    this.#tail = { key: null, val: null, prev: null, next: null };
    this.#head.next = this.#tail;   // empty list: head <-> tail
    this.#tail.prev = this.#head;
  }

  // Remove a node from its current position — O(1)
  // Works for any node because prev and next are always non-null
  #remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  // Insert a node immediately after head (= MRU position) — O(1)
  #insertFront(node) {
    node.next            = this.#head.next;
    node.prev            = this.#head;
    this.#head.next.prev = node;
    this.#head.next      = node;
  }

  // O(1): one hash-map lookup (expected O(1)) + a few pointer writes
  get(key) {
    if (!this.#map.has(key)) return -1;     // cache miss
    const node = this.#map.get(key);        // O(1) map lookup
    this.#remove(node);                     // splice out
    this.#insertFront(node);                // re-insert as MRU
    return node.val;
  }

  // O(1): constant number of map operations and pointer writes
  put(key, val) {
    if (this.#cap <= 0) return;             // capacity 0: never store anything
    if (this.#map.has(key)) {
      // Update existing key: refresh value and move to MRU
      const node = this.#map.get(key);
      node.val   = val;
      this.#remove(node);
      this.#insertFront(node);
    } else {
      if (this.#map.size === this.#cap) {
        // Evict LRU: always this.#tail.prev
        const lru = this.#tail.prev;
        this.#remove(lru);
        this.#map.delete(lru.key);
      }
      const node = { key, val, prev: null, next: null };
      this.#insertFront(node);
      this.#map.set(key, node);
    }
  }
}

// ── Walkthrough with capacity 3 ────────────────────────────────
const lru = new LRUCache(3);
lru.put(1, 'a');  // list: [1]        map: {1}
lru.put(2, 'b');  // list: [2,1]      map: {1,2}
lru.put(3, 'c');  // list: [3,2,1]    map: {1,2,3}  — FULL

console.log(lru.get(1));  // 'a'  list: [1,3,2]   — 1 becomes MRU

lru.put(4, 'd');           // evict LRU=2  list: [4,1,3]  map: {1,3,4}
console.log(lru.get(2));  // -1   — 2 was evicted
console.log(lru.get(3));  // 'c'  list: [3,4,1]   — 3 becomes MRU
console.log(lru.get(4));  // 'd'  list: [4,3,1]

// ── Minimal LRU using only a JavaScript Map ────────────────────
// Map iterates in insertion order, so the FIRST key is the least recently used.
class MapLRU {
  #cap; #map = new Map();
  constructor(capacity) { this.#cap = capacity; }

  get(key) {
    if (!this.#map.has(key)) return -1;
    const val = this.#map.get(key);
    this.#map.delete(key);        // re-insert to move key to the "newest" end
    this.#map.set(key, val);
    return val;
  }

  put(key, val) {
    if (this.#cap <= 0) return;
    this.#map.delete(key);        // no-op if absent; refreshes position if present
    this.#map.set(key, val);
    if (this.#map.size > this.#cap) {
      const oldest = this.#map.keys().next().value;  // LRU key
      this.#map.delete(oldest);
    }
  }
}

const c2 = new MapLRU(2);
c2.put(1, 1); c2.put(2, 2);
c2.put(1, 10);              // update refreshes key 1
c2.put(3, 3);               // evicts key 2, not key 1
console.log(c2.get(2), c2.get(1), c2.get(3)); // -1 10 3

// ── LFU Cache: O(1) get and put ────────────────────────────────
class LFUCache {
  #cap;
  #minFreq;
  #keyMap;   // key -> { value, freq }
  #freqMap;  // freq -> Set<key>  (insertion-order = LRU within bucket)

  constructor(capacity) {
    this.#cap     = capacity;
    this.#minFreq = 0;
    this.#keyMap  = new Map();
    this.#freqMap = new Map();
  }

  // Move key from its current freq bucket to freq+1 bucket — O(1)
  #incrFreq(key) {
    const entry = this.#keyMap.get(key);
    const oldF  = entry.freq;

    // Remove from old bucket
    const oldBucket = this.#freqMap.get(oldF);
    oldBucket.delete(key);
    if (oldBucket.size === 0) {
      this.#freqMap.delete(oldF);
      // If we just emptied the min-freq bucket, min goes up by 1
      // (Only valid here because the trigger was an access, not a new insert)
      if (this.#minFreq === oldF) this.#minFreq++;
    }

    // Add to new bucket
    entry.freq++;
    const newF = entry.freq;
    if (!this.#freqMap.has(newF)) this.#freqMap.set(newF, new Set());
    this.#freqMap.get(newF).add(key);
  }

  // O(1): constant number of Map/Set operations (expected O(1) each)
  get(key) {
    if (!this.#keyMap.has(key)) return -1;
    this.#incrFreq(key);
    return this.#keyMap.get(key).value;
  }

  // O(1): constant number of Map/Set operations
  put(key, value) {
    if (this.#cap <= 0) return;

    if (this.#keyMap.has(key)) {
      // Update existing — increment frequency
      this.#keyMap.get(key).value = value;
      this.#incrFreq(key);
      return;
    }

    // New key — may need to evict
    if (this.#keyMap.size >= this.#cap) {
      // Evict LRU key from the min-freq bucket
      const minBucket = this.#freqMap.get(this.#minFreq);
      // Set.values().next().value = oldest insertion (LRU) — O(1)
      const evictKey  = minBucket.values().next().value;
      minBucket.delete(evictKey);
      if (minBucket.size === 0) this.#freqMap.delete(this.#minFreq);
      this.#keyMap.delete(evictKey);
    }

    // Insert new key with frequency 1
    this.#keyMap.set(key, { value, freq: 1 });
    if (!this.#freqMap.has(1)) this.#freqMap.set(1, new Set());
    this.#freqMap.get(1).add(key);
    this.#minFreq = 1;  // new key always has the minimum frequency
  }
}

// ── Walkthrough: capacity 3 ────────────────────────────────────
const lfu = new LFUCache(3);
lfu.put(1, 'a');  // freq[1]=1  minFreq=1
lfu.put(2, 'b');  // freq[2]=1  minFreq=1
lfu.put(3, 'c');  // freq[3]=1  minFreq=1  FULL

lfu.get(1);       // freq[1]=2  minFreq=1  (key 2 or 3 is LFU)
lfu.get(1);       // freq[1]=3  minFreq=1  (key 2 or 3 is LFU)
lfu.get(2);       // freq[2]=2  minFreq=1  (key 3 is LFU with freq=1)

lfu.put(4, 'd');  // evict LFU=key3 (freq=1, oldest in bucket)
                  // insert key4 with freq=1, minFreq=1
console.log(lfu.get(3));  // -1  (evicted)
console.log(lfu.get(4));  // 'd' freq[4]=2
